import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import ServiceCard from '../components/ServiceCard';
import AppointmentForm from '../components/AppointmentForm';

const Home = () => {
  const { user } = useAuth();
  const [services, setServices] = useState([]);
  const [selectedService, setSelectedService] = useState(null);
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [stylist, setStylist] = useState('');
  const [availableStylists, setAvailableStylists] = useState([]);
  const [availableTimes, setAvailableTimes] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchServices = async () => {
      try {
        const res = await axios.get('/api/services');
        setServices(res.data);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchServices();
  }, []);

  const handleServiceSelect = async (serviceId) => {
    setSelectedService(services.find(s => s._id === serviceId));
    // Fetch stylists for this service
    try {
      const res = await axios.get(`/api/services/${serviceId}`);
      setAvailableStylists(res.data.stylists || []);
    } catch (err) {
      console.error(err);
    }
  };

  const handleDateChange = async (e) => {
    setDate(e.target.value);
    if (selectedService && e.target.value) {
      // Generate time slots (since there's no availability endpoint)
      const slots = [];
      for (let h = 9; h < 18; h++) {
        slots.push(`${String(h).padStart(2, '0')}:00`);
        slots.push(`${String(h).padStart(2, '0')}:30`);
      }
      setAvailableTimes(slots);
    }
  };

  const handleTimeChange = (e) => {
    setTime(e.target.value);
  };

  const handleStylistChange = (e) => {
    setStylist(e.target.value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedService || !date || !time || !stylist) {
      alert('Please fill in all fields');
      return;
    }

    if (!user) {
      alert('Please sign in to book an appointment');
      return;
    }

    try {
      const token = localStorage.getItem('token');
      await axios.post('/api/appointments', {
        stylistId: stylist,
        serviceId: selectedService._id,
        date,
        startTime: time,
        notes: `Booked by ${user.name}`
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert('Appointment booked successfully!');
      // Reset form
      setSelectedService(null);
      setDate('');
      setTime('');
      setStylist('');
      setAvailableStylists([]);
      setAvailableTimes([]);
    } catch (err) {
      console.error(err);
      alert('Failed to book appointment. Please try again.');
    }
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="home-page">
      <h1>Book Your Appointment</h1>

      <div className="service-selection">
        <h2>Choose a Service</h2>
        <div className="services-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '16px' }}>
          {services.map(service => (
            <ServiceCard
              key={service._id}
              service={service}
              onSelect={() => handleServiceSelect(service._id)}
              selected={selectedService?._id === service._id}
            />
          ))}
        </div>
      </div>

      {selectedService && (
        <div className="booking-form" style={{ marginTop: '24px' }}>
          <h2>Book {selectedService.name}</h2>
          <p>{selectedService.description}</p>
          <p><strong>Duration:</strong> {selectedService.duration} minutes</p>
          <p><strong>Price:</strong> ${selectedService.price}</p>

          <AppointmentForm
            service={selectedService}
            date={date}
            time={time}
            stylist={stylist}
            availableStylists={availableStylists}
            availableTimes={availableTimes}
            onDateChange={handleDateChange}
            onTimeChange={handleTimeChange}
            onStylistChange={handleStylistChange}
            onSubmit={handleSubmit}
          />
        </div>
      )}
    </div>
  );
};

export default Home;
